"""Complete own original-field readings, before any boundary candidate is authored."""
NOTES={}
def note(number,language,text):
    key=('deenhindi-muslim:'+number,language)
    assert key not in NOTES
    NOTES[key]=text

note('2484','hi','The entire Hindi is only Ibn Uyaynah/Zuhri transmission with the same chain and an earlier-hadith comparison. No actual body or finite reported saying is present; the spelling defect stays exact in context.')
